class Solution:
    def search(self, nums: List[int], target: int) -> int:
        if target not in nums:
            return -1

        left, right = 0, len(nums) - 1
        while left < right:
            mid = (left + right) // 2
            if nums[mid] == target:
                left = mid
                right = mid + 1
            else:
                mid = mid + 1

        return nums[left]

